-- Complete le fragment_prompt des 3 lignes deja en base, sans ecraser une
-- valeur deja renseignee.
update materiaux set fragment_prompt = 'toiture en tuiles plates terre cuite, pose à recouvrement régulier, teinte flammée du rouge orangé au brun variant d''une tuile à l''autre, relief marqué en lumière rasante, arêtiers et faîtage de même teinte'
  where categorie = 'toiture' and terme = 'Tuiles plates terre cuite' and fragment_prompt is null;
update materiaux set fragment_prompt = 'façade en enduit taloché finition talochée fine, teinte blanc cassé légèrement chaude, grain de surface discret et régulier, variations tonales douces d''une zone à l''autre selon l''exposition à la lumière'
  where categorie = 'facade' and terme = 'Enduit taloché blanc cassé' and fragment_prompt is null;
update materiaux set fragment_prompt = 'menuiseries en aluminium à profils fins, laquage mat gris anthracite RAL 7016, vitrages clairs aux reflets nets, joints d''assemblage discrets, poignées assorties'
  where categorie = 'menuiseries' and terme = 'Menuiseries aluminium anthracite' and fragment_prompt is null;

